import threading, time
def trial(use_lock):
    box = [0]; lk = threading.Lock()
    def f():
        if use_lock: lk.acquire()
        v = box[0]; time.sleep(0.05); box[0] = v + 1
        if use_lock: lk.release()
    ts = [threading.Thread(target=f) for _ in range(2)]
    for t in ts: t.start()
    for t in ts: t.join()
    return box[0]
print('no lock  :', [trial(False) for _ in range(3)])
print('with lock:', [trial(True) for _ in range(3)])

import threading
box = [0]; lk = threading.Lock()
def f():
    for _ in range(100000):
        with lk:
            box[0] += 1
ts = [threading.Thread(target=f) for _ in range(4)]
for t in ts: t.start()
for t in ts: t.join()
print('4 threads x 100000 with a lock:', box[0])
rk = threading.RLock(); lk.acquire(); rk.acquire()
print('Lock again, 0.2 s :', lk.acquire(timeout=0.2))
print('RLock again       :', rk.acquire(timeout=0.2))

